#include <stdio.h>
#include <string.h>

typedef struct {
    int guess;
    char message[20];
} Result;

int main() {
    Result r;
    printf("Enter a number (1-3): ");
    scanf("%d", &r.guess);
    switch (r.guess) {
        case 1:
            strcpy(r.message, "One");
            break;
        case 2:
            strcpy(r.message, "Two");
            break;
        case 3:
            strcpy(r.message, "Three");
            break;
        default:
            strcpy(r.message, "Other");
    }
    printf("Result: %s\n", r.message);
    return 0;
}

